const raw = $input.first().json || {};
const fields = ['agencyName','agencyContact','agencyLogoUrl','destination','tripScope','durationDays','tripTitle','startDate','travelerCount','travelerType','pace','themes','mustInclude','mustAvoid','accommodationNote','heroPhotoUrl','outputLanguage','recipientEmail'];
const labels = ['Agency Name','Agency Contact','Agency Logo URL','Destination','Trip Scope','Duration Days','Trip Title','Start Date','Traveler Count','Traveler Type','Pace','Themes','Must Include','Must Avoid','Accommodation Note','Hero Photo URL','Output Language','Recipient Email'];
const input = { ...raw };
fields.forEach((key, index) => {
  if (input[key] === undefined && raw[labels[index]] !== undefined) input[key] = raw[labels[index]];
  if (input[key] === undefined && raw[`field-${index}`] !== undefined) input[key] = raw[`field-${index}`];
});
const LIMITS = {"agencyName":160,"agencyContact":320,"agencyLogoUrl":2048,"destination":200,"tripScope":32,"durationDays":2,"tripTitle":200,"startDate":10,"travelerCount":6,"travelerType":40,"pace":16,"themes":1000,"mustInclude":3000,"mustAvoid":3000,"accommodationNote":3000,"heroPhotoUrl":2048,"outputLanguage":8,"recipientEmail":320};
const value = (key) => String(input[key] ?? '').trim().slice(0, LIMITS[key]);
const required = ['agencyName','agencyContact','destination','tripScope','recipientEmail'];
const missing = required.filter((key) => !value(key));
if (missing.length) return [{ json: { ok: false, errorCode: 'REQUIRED_FIELD_MISSING', message: `Required field(s) missing: ${missing.join(', ')}`, missing } }];

const tripScope = value('tripScope').toLowerCase();
const modes = ['half_day','full_day','multi_day','destination_guide'];
if (!modes.includes(tripScope)) return [{ json: { ok: false, errorCode: 'INVALID_TRIP_SCOPE', message: 'tripScope must be half_day, full_day, multi_day, or destination_guide.' } }];

const urlFields = ['agencyLogoUrl','heroPhotoUrl'];
for (const key of urlFields) {
  const candidate = value(key);
  if (candidate && !/^https?:\/\/[^\s]+$/i.test(candidate)) return [{ json: { ok: false, errorCode: 'INVALID_URL', field: key, message: `${key} must be an http(s) URL.` } }];
}
const recipientEmail = value('recipientEmail').toLowerCase();
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(recipientEmail)) return [{ json: { ok: false, errorCode: 'INVALID_RECIPIENT_EMAIL', message: 'recipientEmail must be a valid email address.' } }];

const startDate = value('startDate');
if (startDate && !/^\d{4}-\d{2}-\d{2}$/.test(startDate)) return [{ json: { ok: false, errorCode: 'INVALID_START_DATE', message: 'startDate must use YYYY-MM-DD.' } }];

let durationDays = null;
if (tripScope === 'multi_day') {
  const durationRaw = value('durationDays');
  if (!/^\d+$/.test(durationRaw)) return [{ json: { ok: false, errorCode: 'DURATION_REQUIRED', message: 'durationDays is required for multi_day.' } }];
  durationDays = Number(durationRaw);
  if (durationDays < 2 || durationDays > 14) return [{ json: { ok: false, errorCode: 'DURATION_OUT_OF_RANGE', message: 'durationDays must be between 2 and 14 for multi_day.' } }];
}

let travelerCount = null;
if (value('travelerCount')) {
  if (!/^\d+$/.test(value('travelerCount')) || Number(value('travelerCount')) < 1) return [{ json: { ok: false, errorCode: 'INVALID_TRAVELER_COUNT', message: 'travelerCount must be a positive integer.' } }];
  travelerCount = Number(value('travelerCount'));
}

const paceInput = value('pace').toLowerCase();
const paceMap = { relaxed: 'Relaxed', balanced: 'Balanced', packed: 'Packed' };
if (paceInput && !paceMap[paceInput]) return [{ json: { ok: false, errorCode: 'INVALID_PACE', message: 'pace must be relaxed, balanced, or packed.' } }];

const requestedLanguage = value('outputLanguage').toLowerCase() || 'auto';
if (!['auto','id','en'].includes(requestedLanguage)) return [{ json: { ok: false, errorCode: 'INVALID_OUTPUT_LANGUAGE', message: 'outputLanguage must be auto, id, or en.' } }];
let outputLanguage = requestedLanguage;
if (outputLanguage === 'auto') {
  const sample = [value('destination'),value('tripTitle'),value('themes'),value('mustInclude'),value('mustAvoid'),value('accommodationNote')].join(' ').toLowerCase();
  const words = sample.split(/[^a-z]+/).filter(Boolean);
  const idWords = new Set(['yang','dan','di','dengan','untuk','dari','ke','atau','tidak','ingin','kami','saya','pantai','budaya','kuliner','perjalanan','hari']);
  const enWords = new Set(['the','and','in','with','for','from','to','or','not','want','we','beach','culture','food','trip','day']);
  const idScore = words.filter((word) => idWords.has(word)).length;
  const enScore = words.filter((word) => enWords.has(word)).length;
  outputLanguage = idScore >= enScore ? 'id' : 'en';
}

const scopeLabels = outputLanguage === 'id'
  ? { half_day: 'Setengah hari', full_day: 'Satu hari penuh', multi_day: `${durationDays} hari`, destination_guide: 'Panduan destinasi' }
  : { half_day: 'Half day', full_day: 'Full day', multi_day: `${durationDays} days`, destination_guide: 'Destination guide' };
const themes = value('themes').split(',').map((item) => item.trim()).filter(Boolean).slice(0, 30);

return [{ json: {
  ok: true,
  schemaVersion: '2.0.0',
  agencyName: value('agencyName'),
  agencyContact: value('agencyContact'),
  agencyLogoUrl: value('agencyLogoUrl') || null,
  destination: value('destination'),
  tripScope,
  itineraryMode: tripScope,
  durationDays,
  tripTitle: value('tripTitle') || null,
  startDate: startDate || null,
  travelerCount,
  travelerType: value('travelerType') || null,
  pace: paceMap[paceInput] || 'Balanced',
  paceLevel: paceMap[paceInput] || 'Balanced',
  themes,
  mustInclude: value('mustInclude') || null,
  mustAvoid: value('mustAvoid') || null,
  accommodationNote: tripScope === 'multi_day' ? (value('accommodationNote') || null) : null,
  heroPhotoUrl: value('heroPhotoUrl') || null,
  requestedOutputLanguage: requestedLanguage,
  outputLanguage,
  recipientEmail,
  scopeLabel: scopeLabels[tripScope],
  destinationType: 'mixed',
  limitsApplied: LIMITS
} }];

const item = $input.first().json || {};
if (item.ok !== true) return [{ json: item }];
const palettes = {
  beach: { primary: '#0F766E', secondary: '#155E75', accent: '#CFF5ED', surface: '#F7F8FA', textDark: '#102A43', textMuted: '#667085', gradientStops: ['#0B3B46','#0F766E','#66C7B8'] },
  mountain: { primary: '#243B53', secondary: '#3B6978', accent: '#D7E9E8', surface: '#F7F8FA', textDark: '#172B4D', textMuted: '#667085', gradientStops: ['#172B4D','#243B53','#3B6978'] },
  city: { primary: '#334E68', secondary: '#2563EB', accent: '#E8F0FF', surface: '#F7F8FA', textDark: '#111827', textMuted: '#667085', gradientStops: ['#172B4D','#334E68','#2563EB'] },
  cultural: { primary: '#3B4D6B', secondary: '#0F766E', accent: '#E6F4F1', surface: '#F7F8FA', textDark: '#111827', textMuted: '#667085', gradientStops: ['#172B4D','#3B4D6B','#0F766E'] },
  nature: { primary: '#166534', secondary: '#0F766E', accent: '#E2F4EA', surface: '#F7F8FA', textDark: '#102A43', textMuted: '#667085', gradientStops: ['#14532D','#166534','#0F766E'] },
  desert: { primary: '#4B5563', secondary: '#B7791F', accent: '#FFF4D6', surface: '#F7F8FA', textDark: '#111827', textMuted: '#667085', gradientStops: ['#374151','#4B5563','#B7791F'] },
  mixed: { primary: '#172B4D', secondary: '#0F766E', accent: '#DFF4F0', surface: '#F7F8FA', textDark: '#111827', textMuted: '#667085', gradientStops: ['#102A43','#155E75','#0F766E'] }
};
const paletteKey = Object.hasOwn(palettes, item.destinationType) ? item.destinationType : 'mixed';
return [{ json: { ...item, destinationType: paletteKey, paletteKey, palette: palettes[paletteKey] } }];

const intake = $input.first().json;
if (intake.ok !== true) return [{ json: intake }];
const requiredKeys = ['destinationType','paceLevel','themes','tripTitle','region','country','modeConfirm'];
const prompt = `Interpret this travel brief and return ONLY valid JSON with exactly these keys: destinationType, paceLevel, themes, tripTitle, region, country, modeConfirm.

Controlled values:
- destinationType: beach | mountain | city | cultural | nature | desert | mixed
- paceLevel: Relaxed | Balanced | Packed
- themes: array of short strings
- modeConfirm: half_day | full_day | multi_day | destination_guide

Rules:
- modeConfirm must reflect itineraryMode but is confirmation only; it cannot change the resolved mode.
- Do not produce schedules, spots, venue claims, prices, opening hours, or ticket prices.
- Write tripTitle, region, country, and themes in ${intake.outputLanguage === 'en' ? 'English' : 'Indonesian'}.
- Infer only from supplied input. Use an empty string for an unknown region; country must be a best-effort geographic identification.
- Return all keys exactly once.

Input JSON:
${JSON.stringify({destination:intake.destination,itineraryMode:intake.itineraryMode,durationDays:intake.durationDays,tripTitle:intake.tripTitle,paceLevel:intake.paceLevel,themes:intake.themes,mustInclude:intake.mustInclude,mustAvoid:intake.mustAvoid,accommodationNote:intake.accommodationNote,outputLanguage:intake.outputLanguage})}`;
return [{ json: { ...intake, briefRequiredKeys: requiredKeys, requestBody: { model: 'vertex_ai/openai/gpt-oss-120b-maas', reasoning: { effort: 'low' }, messages: [
  { role: 'system', content: 'You are a careful travel brief interpreter. Return strict JSON only and never override the authoritative itinerary mode.' },
  { role: 'user', content: prompt }
], temperature: 0.1, max_output_tokens: 1600 } } }];

const response = $input.first().json || {};
const source = $('Build Brief Request').first().json;
const messages = Array.isArray(response.output) ? response.output.filter((entry) => entry?.type === 'message') : [];
const last = messages[messages.length - 1];
const raw = last?.content?.map((part) => part?.text || part?.content || '').join('') || response.choices?.[0]?.message?.content || '';
const strip = (value) => String(value || '').trim().replace(/^\`\`\`json\s*/i, '').replace(/^\`\`\`\s*/, '').replace(/\s*\`\`\`$/, '').trim();
const parseJson = (value) => {
  const clean = strip(value);
  try { return JSON.parse(clean); } catch (_) {
    const start = clean.indexOf('{');
    const end = clean.lastIndexOf('}');
    if (start >= 0 && end > start) {
      try { return JSON.parse(clean.slice(start, end + 1)); } catch (_) {}
    }
    return null;
  }
};
const parsed = parseJson(raw);
const destinationTypes = ['beach','mountain','city','cultural','nature','desert','mixed'];
const paceLevels = ['Relaxed','Balanced','Packed'];
const modes = ['half_day','full_day','multi_day','destination_guide'];
const cap = (value, max) => String(value ?? '').trim().slice(0, max);
const themes = Array.isArray(parsed?.themes) ? parsed.themes.map((v) => cap(v, 80)).filter(Boolean).slice(0, 30) : null;
const valid = Boolean(parsed && destinationTypes.includes(parsed.destinationType) && paceLevels.includes(parsed.paceLevel) && themes && themes.length && cap(parsed.tripTitle, 200) && cap(parsed.country, 120) && modes.includes(parsed.modeConfirm));
const brief = valid ? {
  destinationType: parsed.destinationType,
  paceLevel: parsed.paceLevel,
  themes,
  tripTitle: cap(parsed.tripTitle, 200),
  region: cap(parsed.region, 120) || null,
  country: cap(parsed.country, 120),
  modeConfirm: parsed.modeConfirm
} : null;
return [{ json: {
  ...source,
  requestBody: undefined,
  briefRequiredKeys: undefined,
  brief,
  briefOk: valid,
  destinationType: valid ? brief.destinationType : source.destinationType,
  paceLevel: valid ? brief.paceLevel : source.paceLevel,
  pace: valid ? brief.paceLevel : source.pace,
  themes: valid ? brief.themes : source.themes,
  tripTitle: valid ? brief.tripTitle : source.tripTitle,
  region: valid ? brief.region : null,
  country: valid ? brief.country : null,
  modeConfirm: valid ? brief.modeConfirm : null,
  modeConflictIgnored: valid ? brief.modeConfirm !== source.itineraryMode : false,
  itineraryMode: source.itineraryMode,
  tripScope: source.tripScope,
  durationDays: source.durationDays,
  errorCode: valid ? undefined : 'BRIEF_INTERPRETATION_FAILED',
  rawBriefText: valid ? undefined : cap(raw, 1000)
} }];

const item = $input.first().json || {};
if (item.ok !== true) return [{ json: item }];
const palettes = {
  beach: { primary: '#087F8C', secondary: '#FF6B6B', accent: '#F4D6A0', surface: '#FFF9EF', textDark: '#16343A', textMuted: '#60777A', gradientStops: ['#087F8C','#22B8B2','#FF8B7B'] },
  mountain: { primary: '#24513B', secondary: '#52616B', accent: '#D8A657', surface: '#FFF7E8', textDark: '#1E3028', textMuted: '#68756F', gradientStops: ['#183D2D','#3E6B50','#D8A657'] },
  city: { primary: '#3F46A5', secondary: '#F2A900', accent: '#FFC857', surface: '#F3F5F8', textDark: '#20243D', textMuted: '#6C7085', gradientStops: ['#30378F','#636BC7','#F2A900'] },
  cultural: { primary: '#B55239', secondary: '#4B2E24', accent: '#D99B6C', surface: '#FFF4DF', textDark: '#38241F', textMuted: '#7C675F', gradientStops: ['#8E3B2A','#C76648','#E2B27A'] },
  nature: { primary: '#256D3A', secondary: '#84B547', accent: '#B9D96B', surface: '#FAFBEF', textDark: '#183622', textMuted: '#657467', gradientStops: ['#1D5B31','#4E8C46','#A9CF58'] },
  desert: { primary: '#C75B28', secondary: '#C88A2E', accent: '#E8B55B', surface: '#FFF2D2', textDark: '#4A2C1E', textMuted: '#806A59', gradientStops: ['#AD4720','#D57832','#E8B55B'] },
  mixed: { primary: '#203A5F', secondary: '#D9795F', accent: '#F0B67F', surface: '#F7F4EF', textDark: '#1E2B3A', textMuted: '#687381', gradientStops: ['#203A5F','#496A86','#D9795F'] }
};
const paletteKey = Object.hasOwn(palettes, item.destinationType) ? item.destinationType : 'mixed';
return [{ json: { ...item, destinationType: paletteKey, paletteKey, palette: palettes[paletteKey] } }];

const intake = $input.first().json || {};
if (intake.ok !== true) return [{ json: intake }];
const scheduled = ['half_day','full_day','multi_day'].includes(intake.itineraryMode);
const activityKeys = ['timeLabel','type','title','description','durationLabel'];
const blockKeys = ['blockNumber','blockLabel','blockRangeLabel','date','title','location','isCondensed','activities','accommodation','mealsIncluded','transportNote','blockTip'];
const spotKeys = ['groupLabel','name','area','category','description','suggestedDuration','bestTimeToVisit','gettingThere','tips','nearbyPairing'];
const anchorRules = intake.routePlanProvided
  ? `\nROUTE ANCHORS (fixed, do not violate): routePlanOrdered below gives the exact visiting order per block, already decided by the trip operator on the ground. Reproduce every anchor, inside the block number given, in the exact order given. You may add filler activities (transport, meals, short stops) between anchors. You may NOT reorder an anchor, move it to a different block, skip it, or invent a substitute for it. Blocks beyond routePlanOrdered's block count are yours to plan freely. If ${'outputLanguage'} requires a natural translation of an anchor's name, keep it recognizably the same place, never a different one.`
  : '';
const commonRules = `AUTHORITATIVE MODE: ${intake.itineraryMode}. Never change it.
Honor mustInclude and mustAvoid. Return strict JSON only.
No monetary figure or currency value. No opening hours or ticket prices.
No booking CTA, ratings, review counts, availability/scarcity claims, bare feature checklists, or empty superlative filler.
Every entry must explain why it matters. Activity descriptions must orient the traveler rather than restate titles.
Do not include photos. Do not generate overview, practical, closing, route summary, highlights, or other sections handled by later stages.
Write prose in ${intake.outputLanguage === 'en' ? 'English' : 'Indonesian'}.${anchorRules}`;
let shapeRules;
let requiredKeys;
if (scheduled) {
  requiredKeys = { root: ['schedule','spots'], scheduleBlock: blockKeys, activity: activityKeys };
  const modeRules = intake.itineraryMode === 'multi_day'
    ? `Create coverage for exactly ${intake.durationDays} days. Days 1-7 must each be full individual blocks. For days 8-${intake.durationDays}, condense similar consecutive days into numeric range blocks such as "Hari 8–9"; set isCondensed=true. Include accommodation for each multi-day block and mealsIncluded.`
    : `Create exactly one continuous block. blockLabel and blockRangeLabel must be null, isCondensed=false, and accommodation must be null. Meals may be an empty array.`;
  shapeRules = `Return exactly {"schedule":[...],"spots":[]}. schedule must be non-empty and spots must be empty.
Each schedule block has exactly these keys: ${blockKeys.join(', ')}.
Each activity has exactly these keys: ${activityKeys.join(', ')}.
activity.type must be one of transport, sightseeing, food, activity, rest, accommodation, free.
Every block needs at least one activity. timeLabel is required for every activity.
${modeRules}`;
} else {
  requiredKeys = { root: ['schedule','spots'], spot: spotKeys };
  shapeRules = `Return exactly {"schedule":[],"spots":[...]}. spots must be non-empty and schedule must be empty.
Each spot has exactly these keys: ${spotKeys.join(', ')}.
Never include a clock time (for example 09:00 or 9 AM) or a committed visit sequence.
Each spot description must be substantive 40-90 words. suggestedDuration, bestTimeToVisit, gettingThere, and at least one genuinely actionable tip are required. Include honest caveats and nearbyPairing context.
For 1-8 spots use a flat list with groupLabel null. For 9+ spots, group every spot by area or theme using a non-empty groupLabel; preserve full guidance depth rather than thinning entries.
If the requested breadth cannot meet this quality floor within the output budget, return {"schedule":[],"spots":[],"error":"QUALITY_FLOOR_CAPACITY"} rather than thin content.`;
}
const prompt = `Create the itinerary body skeleton.
${commonRules}
${shapeRules}

Required key manifest:
${JSON.stringify(requiredKeys)}

Input:
${JSON.stringify({destination:intake.destination,region:intake.region,country:intake.country,tripTitle:intake.tripTitle,itineraryMode:intake.itineraryMode,durationDays:intake.durationDays,startDate:intake.startDate,travelerCount:intake.travelerCount,travelerType:intake.travelerType,paceLevel:intake.paceLevel,themes:intake.themes,mustInclude:intake.mustInclude,mustAvoid:intake.mustAvoid,accommodationNote:intake.accommodationNote,outputLanguage:intake.outputLanguage,routePlanOrdered: intake.routePlanProvided ? intake.routePlanOrdered : undefined})}`;
return [{ json: { ...intake, skeletonRequiredKeys: requiredKeys, requestBody: { model: 'openai/gpt-5.6-luna', reasoning: { effort: 'medium' }, input: [
  { role: 'system', content: [{ type: 'input_text', text: 'You design practical itinerary structures. Obey the authoritative mode and return strict JSON only.' }] },
  { role: 'user', content: [{ type: 'input_text', text: prompt }] }
], temperature: 0.2, max_output_tokens: 12000 } } }];

const response = $input.first().json || {};
const source = $('Build Skeleton Request').first().json;
const messages = Array.isArray(response.output) ? response.output.filter((entry) => entry?.type === 'message') : [];
const last = messages[messages.length - 1];
const raw = last?.content?.map((part) => part?.text || part?.content || '').join('') || response.choices?.[0]?.message?.content || '';
const strip = (value) => String(value || '').trim().replace(/^\`\`\`json\s*/i, '').replace(/^\`\`\`\s*/, '').replace(/\s*\`\`\`$/, '').trim();
const parseJson = (value) => { const clean = strip(value); try { return JSON.parse(clean); } catch (_) { const a = clean.indexOf('{'); const b = clean.lastIndexOf('}'); if (a >= 0 && b > a) try { return JSON.parse(clean.slice(a, b + 1)); } catch (_) {} return null; } };
const parsed = parseJson(raw);
const cap = (value, max = 1000) => String(value ?? '').trim().slice(0, max);
const array = (value) => Array.isArray(value) ? value : [];
const currencyFigure = /(?:[$€£¥]|Rp\.?|IDR|USD|EUR|GBP|AUD|SGD)\s*\d|\d\s*(?:IDR|USD|EUR|GBP|AUD|SGD)\b/i;
const openingClaim = /(?:buka|open(?:ing)?\s+hours?|jam\s+operasional)[^\n]{0,40}\b\d{1,2}[.:]\d{2}\b/i;
const serialized = parsed ? JSON.stringify(parsed) : '';
let failure = null;
if (!parsed || typeof parsed !== 'object') failure = 'UNPARSEABLE';
else if (currencyFigure.test(serialized)) failure = 'MONETARY_FIGURE';
else if (openingClaim.test(serialized)) failure = 'OPENING_HOURS_CLAIM';
const activityTypes = ['transport','sightseeing','food','activity','rest','accommodation','free'];
const normalizeActivity = (a) => ({ timeLabel: cap(a?.timeLabel, 40), type: cap(a?.type, 32), title: cap(a?.title, 200), description: cap(a?.description, 1200), durationLabel: cap(a?.durationLabel, 80) || null });
const defaultAccommodationNote = source.outputLanguage === 'en' ? 'Choose an overnight stay near this day’s location.' : 'Pilih akomodasi yang dekat dengan lokasi hari ini.';
const normalizeBlock = (b) => ({
  blockNumber: Number.isInteger(Number(b?.blockNumber)) && Number(b?.blockNumber) > 0 ? Number(b.blockNumber) : null,
  blockLabel: cap(b?.blockLabel, 100) || null,
  blockRangeLabel: cap(b?.blockRangeLabel, 100) || null,
  date: cap(b?.date, 10) || null,
  title: cap(b?.title, 200),
  location: cap(b?.location, 200),
  isCondensed: Boolean(b?.isCondensed),
  activities: array(b?.activities).map(normalizeActivity),
  accommodation: b?.accommodation && typeof b.accommodation === 'object' ? { name: cap(b.accommodation.name, 200) || null, area: cap(b.accommodation.area, 200) || cap(b?.location, 200), note: cap(b.accommodation.note, 600) || defaultAccommodationNote } : (b?.blockNumber ? { name: null, area: cap(b?.location, 200), note: defaultAccommodationNote } : null),
  mealsIncluded: array(b?.mealsIncluded).map((v) => cap(v, 100)).filter(Boolean),
  transportNote: cap(b?.transportNote, 600) || null,
  blockTip: cap(b?.blockTip, 600) || null
});
const normalizeSpot = (s) => ({
  groupLabel: cap(s?.groupLabel, 120) || null,
  name: cap(s?.name, 200), area: cap(s?.area, 200), category: cap(s?.category, 100),
  description: cap(s?.description, 1500), suggestedDuration: cap(s?.suggestedDuration, 120),
  bestTimeToVisit: cap(s?.bestTimeToVisit, 200), gettingThere: cap(s?.gettingThere, 800),
  tips: (Array.isArray(s?.tips) ? s.tips : (typeof s?.tips === 'string' ? s.tips.split(/\\s*(?:;|\\n|\\|)\\s*/).filter(Boolean) : [])).map((v) => cap(v, 500)).filter(Boolean).slice(0, 12),
  nearbyPairing: cap(s?.nearbyPairing, 500) || null
});
const schedule = array(parsed?.schedule).map(normalizeBlock);
const spots = array(parsed?.spots).map(normalizeSpot);
const scheduledMode = ['half_day','full_day','multi_day'].includes(source.itineraryMode);
if (!failure && scheduledMode && (!schedule.length || spots.length)) failure = 'BODY_SHAPE_MISMATCH';
if (!failure && !scheduledMode && (schedule.length || !spots.length)) failure = 'BODY_SHAPE_MISMATCH';
if (!failure && scheduledMode) {
  if (schedule.some((b) => !b.title || !b.location || !b.activities.length || b.activities.some((a) => !a.timeLabel || !a.title || !a.description || !activityTypes.includes(a.type)))) failure = 'INVALID_SCHEDULE_BLOCK';
  if (!failure && ['half_day','full_day'].includes(source.itineraryMode) && (schedule.length !== 1 || schedule[0].blockLabel || schedule[0].blockRangeLabel || schedule[0].isCondensed)) failure = 'SINGLE_DAY_SHAPE_MISMATCH';
  if (!failure && source.itineraryMode === 'multi_day') {
    if (schedule.some((b) => !b.accommodation || !b.accommodation.area || !b.accommodation.note)) failure = 'ACCOMMODATION_REQUIRED';
    const covered = [];
    let hasCondensedRange = false;
    for (const block of schedule) {
      if (block.blockRangeLabel) {
        const nums = block.blockRangeLabel.match(/\d+/g)?.map(Number) || [];
        if (nums.length >= 2 && nums[1] >= nums[0]) {
          for (let day = nums[0]; day <= nums[1]; day++) covered.push(day);
          if (nums[1] > nums[0] && block.isCondensed) hasCondensedRange = true;
        } else if (nums.length === 1) covered.push(nums[0]); else failure = 'INVALID_DAY_RANGE';
      } else if (block.blockNumber) covered.push(block.blockNumber);
      else failure = 'MISSING_DAY_NUMBER';
    }
    const expected = Array.from({length: source.durationDays}, (_, i) => i + 1);
    const unique = [...new Set(covered)].sort((a,b) => a-b);
    if (!failure && JSON.stringify(unique) !== JSON.stringify(expected)) failure = 'DAY_COVERAGE_MISMATCH';
    if (!failure && source.durationDays > 7) {
      const firstSevenIndividual = expected.slice(0,7).every((day) => schedule.some((b) => b.blockNumber === day && !b.blockRangeLabel && !b.isCondensed));
      if (!firstSevenIndividual || !hasCondensedRange) failure = 'CONDENSING_REQUIRED';
    }
